package tree

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strings"
	"text/template"
)

const sdkImport = "github.com/scientist-labs/pharmaobservatory-sdks/go"

// File is one generated file.
type File struct {
	Name string
	Data []byte
}

func pascal(s string) string {
	var b strings.Builder
	for _, part := range strings.FieldsFunc(s, func(r rune) bool { return r == '-' || r == '_' }) {
		b.WriteString(strings.ToUpper(part[:1]) + part[1:])
	}
	return b.String()
}

func ident(o Op) string {
	switch o.Kind {
	case KindList:
		return "op" + pascal(o.Page) + "List"
	case KindGet:
		return "op" + pascal(o.Page) + "Get"
	case KindIDSection:
		return "op" + pascal(o.Page) + "GetSection" + pascal(o.Key)
	}
	return "op" + pascal(o.Page) + "Section" + pascal(o.Key)
}

type pageView struct {
	Slug    string
	Ident   string
	Escaped bool
	Ops     []opView
	List    string
	Get     string
	IDSecs  []string
	Secs    []string
}

type opView struct {
	Op
	Ident string
}

var opTmpl = template.Must(template.New("op").Funcs(template.FuncMap{"q": func(s string) string { return fmt.Sprintf("%q", s) }}).Parse(`
func {{.Ident}}() *Op {
	fs := pflag.NewFlagSet({{q .Op.OperationID}}, pflag.ContinueOnError)
{{- range .Params}}
	fs.{{.Define}}({{q .Flag}}, {{if eq .Type "string"}}""{{else if eq .Type "boolean"}}false{{else}}0{{end}}, {{q .Desc}})
{{- end}}
	return &Op{
		Key: {{q .Key}}, Short: {{q .Summary}}, Path: {{q .Path}}, Escaped: {{.Escaped}}, Flags: fs,
		Call: func(ctx context.Context, cl *sdk.APIClient, id string, fs *pflag.FlagSet) (*http.Response, error) {
			{{if .HasID}}r := cl.{{.Service}}.{{.Method}}(ctx, id){{else}}_ = id
			r := cl.{{.Service}}.{{.Method}}(ctx){{end}}
{{- range .Params}}
			if fs.Changed({{q .Flag}}) {
				v, err := fs.{{.Getter}}({{q .Flag}})
				if err != nil {
					return nil, err
				}
				r = r.{{.Setter}}(v)
			}
{{- end}}
			_, resp, err := r.Execute()
			return resp, err
		},
	}
}
`))

var pageTmpl = template.Must(template.New("page").Funcs(template.FuncMap{"q": func(s string) string { return fmt.Sprintf("%q", s) }}).Parse(`// Code generated by internal/gen from {{.Module}} {{.Version}}; DO NOT EDIT.

package pages

import (
	"context"
	"net/http"

	"github.com/spf13/pflag"

	sdk "{{.SDKImport}}"
)

func page{{.Page.Ident}}() *PageSpec {
	return &PageSpec{
		Slug: {{q .Page.Slug}}, Escaped: {{.Page.Escaped}},
{{- if .Page.List}}
		List: {{.Page.List}}(),
{{- end}}
{{- if .Page.Get}}
		Get: {{.Page.Get}}(),
{{- end}}
		IDSections: []*Op{ {{range .Page.IDSecs}}{{.}}(), {{end}} },
		Sections:   []*Op{ {{range .Page.Secs}}{{.}}(), {{end}} },
	}
}
`))

var indexTmpl = template.Must(template.New("index").Funcs(template.FuncMap{"q": func(s string) string { return fmt.Sprintf("%q", s) }}).Parse(`// Code generated by internal/gen from {{.Module}} {{.Version}}; DO NOT EDIT.

package pages

// SDKVersion is the pinned SDK release this tree was generated from.
const SDKVersion = {{q .Version}}

func allPages() []*PageSpec {
	return []*PageSpec{
{{- range .Pages}}
		page{{.}}(),
{{- end}}
	}
}

// Operations is every generated page operation, for the tests that compare it with the document.
var Operations = []OpRef{
{{- range .Ops}}
	{Page: {{q .Page}}, Kind: {{q .Kind}}, Key: {{q .Key}}, Path: {{q .Path}}},
{{- end}}
}

// Unmapped are the document's operations that are not page operations. Each must be hand-mapped
// and listed in the allowlist test.
var Unmapped = []string{
{{- range .Unmapped}}
	{{q .}},
{{- end}}
}
`))

// Render produces the generated files for the model, sorted by name.
func Render(m *Model) ([]File, error) {
	byPage := map[string]*pageView{}
	idents := map[string]string{}
	var pageIdents []string
	opsOf := map[string][]opView{}
	for _, o := range m.Ops {
		id := ident(o)
		if prev, dup := idents[id]; dup {
			return nil, fmt.Errorf("generated identifier %s is produced by both %s and %s", id, prev, o.Path)
		}
		idents[id] = o.Path
		v := byPage[o.Page]
		if v == nil {
			pi := pascal(o.Page)
			v = &pageView{Slug: o.Page, Ident: pi, Escaped: PageEscaped(o.Page)}
			byPage[o.Page] = v
			pageIdents = append(pageIdents, pi)
		}
		switch o.Kind {
		case KindList:
			v.List = id
		case KindGet:
			v.Get = id
		case KindIDSection:
			v.IDSecs = append(v.IDSecs, id)
		case KindSection:
			v.Secs = append(v.Secs, id)
		}
		opsOf[o.Page] = append(opsOf[o.Page], opView{Op: o, Ident: id})
	}
	sort.Strings(pageIdents)
	var files []File
	for _, slug := range m.Pages {
		v := byPage[slug]
		var buf bytes.Buffer
		if err := pageTmpl.Execute(&buf, map[string]any{"Module": m.SDKModule, "Version": m.SDKVersion, "SDKImport": sdkImport, "Page": v}); err != nil {
			return nil, err
		}
		for _, ov := range opsOf[slug] {
			if err := opTmpl.Execute(&buf, ov); err != nil {
				return nil, err
			}
		}
		src, err := format.Source(buf.Bytes())
		if err != nil {
			return nil, fmt.Errorf("page %s: generated code does not parse: %w\n%s", slug, err, buf.String())
		}
		files = append(files, File{Name: "zz_generated_" + strings.ReplaceAll(slug, "-", "_") + ".go", Data: src})
	}
	var buf bytes.Buffer
	if err := indexTmpl.Execute(&buf, map[string]any{"Module": m.SDKModule, "Version": m.SDKVersion, "Pages": pageIdents, "Ops": m.Ops, "Unmapped": m.Unmapped}); err != nil {
		return nil, err
	}
	src, err := format.Source(buf.Bytes())
	if err != nil {
		return nil, err
	}
	files = append(files, File{Name: "zz_generated_index.go", Data: src})
	sort.Slice(files, func(i, j int) bool { return files[i].Name < files[j].Name })
	return files, nil
}
